const b = $input.first().json.body || {};
const h = $input.first().json.headers || {};
if (h['x-l10n-secret'] !== '0b188a84e0d6edf3a44f9e664f33a530') throw new Error('bad secret');
const MODE = b.mode; if (!['check','one','all','screens'].includes(MODE)) throw new Error('bad mode');
const P = b.P || [];
return [{ json: { MODE, TAGS: ['IQTST-903','IQTST-1005'], P, ids: P.map(p => p[0]).join(','), screens: b.screens || [] } }];

const cfg = $('Params').first().json;
const want = {}; for (const p of cfg.P) want[p[0]] = { desc: p[1], es: p[2] };
const keys = ($('Get Current').first().json.keys) || [];
const ups = []; const skipped = []; let nTag=0,nDesc=0,nEs=0;
for (const k of keys) {
  const w = want[k.key_id]; if (!w) continue;
  if (k.is_archived) { skipped.push([k.key_id,'archived']); continue; }
  const u = { key_id: k.key_id };
  const missing = cfg.TAGS.filter(t => !(k.tags || []).includes(t));
  if (missing.length) { u.tags = missing; u.merge_tags = true; nTag++; }
  if (!(k.description || '').trim()) { u.description = w.desc; nDesc++; }
  else skipped.push([k.key_id,'description already set']);
  const es = (k.translations || []).find(t => t.language_iso === 'es');
  if (k.is_plural) skipped.push([k.key_id,'plural key - ES not written']);
  else if (es && typeof es.translation === 'string' && es.translation.trim()) skipped.push([k.key_id,'ES not empty: ' + (es.modified_by_email||'')]);
  else { u.translations = [{ language_iso: 'es', translation: w.es, is_unverified: true }]; nEs++; }
  if (Object.keys(u).length > 1) ups.push(u);
}
const summary = { mode: cfg.MODE, found: keys.length, expected: cfg.P.length, updates: ups.length, tagged: nTag, descriptions: nDesc, es: nEs, skipped };
if (cfg.MODE === 'check') return [{ json: { summary, sample: ups.slice(0,2), write: false } }];
const list = cfg.MODE === 'one' ? ups.slice(0,1) : ups;
const out = [];
for (let i = 0; i < list.length; i += 40) out.push({ json: { body: { keys: list.slice(i, i + 40) }, summary, write: true } });
if (!out.length) return [{ json: { summary, write: false } }];
return out;

const cfg = $('Params').first().json;
const want = {}; for (const p of cfg.P) want[p[0]] = p;
const keys = ($('Read Back').first().json.keys) || [];
let tagsOk=0, descOk=0, esOk=0, unver=0; const bad=[];
for (const k of keys) {
  const w = want[k.key_id]; if (!w) continue;
  if (cfg.TAGS.every(t => (k.tags||[]).includes(t))) tagsOk++;
  if ((k.description||'') === w[1]) descOk++;
  const es = (k.translations||[]).find(t => t.language_iso === 'es') || {};
  if (es.translation === w[2]) { esOk++; if (es.is_unverified) unver++; }
  else bad.push({ key_id: k.key_id, name: (k.key_name||{}).web, es: es.translation, by: es.modified_by_email });
}
const s = $('Build').first().json.summary;
return [{ json: { build: s, writeCalls: $('WRITE Keys').all().length, checked: keys.length, tagsOk, descOk, esOk, esUnverified: unver, mismatched: bad.length, bad: bad.slice(0,10), tagsSample: keys.slice(0,2).map(k => k.tags) } }];
